contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint32 initialStateChoice) public {
        require(initialStateChoice <= 2, "invalid choice");

        if (initialStateChoice == 1) {
            c.sync();
        }

        uint256 beforeRState = c._RState_();
        uint256 beforeBaseReserve = c._BASE_RESERVE_();
        uint256 beforeQuoteReserve = c._QUOTE_RESERVE_();
        uint256 beforeBaseTarget = c._BASE_TARGET_();
        uint256 beforeQuoteTarget = c._QUOTE_TARGET_();

        c.correctRState();

        uint256 afterBaseTarget = c._BASE_TARGET_();
        uint256 afterQuoteTarget = c._QUOTE_TARGET_();

        bool ruleHolds = true;
        if (beforeRState == 1) {
            if (beforeBaseReserve < beforeBaseTarget) {
                ruleHolds = (afterQuoteTarget == beforeQuoteReserve);
            } else {
                ruleHolds = (afterQuoteTarget == beforeQuoteTarget);
            }
        } else if (beforeRState == 2) {
            if (beforeQuoteReserve < beforeQuoteTarget) {
                ruleHolds = (afterQuoteTarget == beforeQuoteReserve);
            } else {
                ruleHolds = (afterQuoteTarget == beforeQuoteTarget);
            }
        } else {
            ruleHolds = (afterQuoteTarget == beforeQuoteTarget);
        }

        assert(ruleHolds);
    }

    receive() external payable {}
}

